        "intro": "当PINNs遇到激波、不连续解等复杂守恒律问题时，单一神经网络往往力不从心。布朗大学Jagtap团队在计算力学顶刊CMAME上提出的守恒型物理信息神经网络(cPINN)，通过域分解策略让每个子区域使用专属网络，并在界面强制守恒量连续。这项研究不仅大幅提升了PINNs求解守恒律方程的精度，更为科学计算中的并行化和多尺度问题提供了新思路。",
