                "method": "方法流程可以这样理解：①标准PINN的损失=数据拟合误差 + PDE残差平方 + 边界条件误差；②gPINN在此基础上增加'梯度损失'：对每个残差点，计算PDE残差f关于输入坐标(x, t等)的偏导数∂f/∂x、∂f/∂t；③将这些梯度项的平方也加入损失函数，权重系数通过网格搜索确定；④对于d维问题，额外增加d个损失项，计算成本约为原来的1.5-2倍。以一维Poisson方程为例：原损失只惩罚f=-u''-g偏离零，现在还要惩罚∂f/∂x也偏离零。这迫使网络不仅让残差小，还让残差变化平缓。",
                "innovation": "①将'残差的梯度也应为零'这一数学直觉转化为可操作的损失项，形式简洁且通用；②发现不同方程对梯度权重敏感度差异巨大：Poisson方程需精心调参(最优值0.01)，而扩散-反应方程对权重不敏感(0.01-1均可)；③与RAR方法的协同效应：gPINN让每个训练点更有效，RAR让训练点分布更合理，两者结合在陡峭解问题(如Burgers方程)中相得益彰，用700个点即可达到标准PINN用4000个点的精度"
