                "problem": "核心困境是：如何让PINNs从'实验室玩具'变成'工程工具'？Lu Lu团队的切入点是打造专门的软件库：既要封装底层复杂性（自动微分、优化器选择、网络架构），又要保持足够的灵活性（支持自定义方程、边界条件、几何形状）。更高的目标是让用户代码'看起来像数学'——定义方程就像在纸上写公式一样自然，而不是在代码的海洋中迷失。这就是DeepXDE的设计哲学：用最少的代码表达最完整的数学意图。"
