                "method": "① 构建多输出神经网络：不同于传统PINN仅输出方程中的未知函数u(x,t)，A-PINN的网络同时输出主变量u和辅助变量I（代表积分值），形成[u, I]的联合输出；\n\n ② 建立辅助变量的微分约束：根据微积分基本定理，积分∫f(s)ds对上限x的导数等于f(x)。因此对辅助输出I(x,t)求导，令∂I/∂x = f(x,t)，将积分关系转化为可自动微分的导数方程；\n\n ③ 设计多重损失函数：总损失包括四部分——主变量的初边界条件误差、辅助变量的初始条件误差（如I(x₀,t)=0）、原方程残差（用I替代积分项）、以及新增的辅助方程残差（∂I/∂x与被积函数的差值）；\n\n ④ 端到端训练优化：网络参数通过最小化总损失同步更新，自动学习满足所有约束的解。整个过程完全连续，无需任何积分离散化步骤。",
