                "problem": "核心问题是：如何把'物理必须满足'与'数据可能出错'放在同一概率框架下？布朗团队给出的钥匙是贝叶斯定理：把PDE残差、边界条件、观测数据全部写成概率因子，让网络权重变成随机变量——于是噪声不再是被压制的敌人，而是被显式建模的信息源。"
